CREATE TABLE tb_demo
(
    "serial"                    serial PRIMARY KEY,
    "smallserial"               smallserial,
    "bigserial"                 bigserial,
    "bigint"                    bigint generated by default as identity,
    "bigint2"                   bigint,
    "bigint_arr"                bigint[],
    "bit"                       bit(5),
    "bit_varying"               bit varying(255),
    "boolean"                   boolean,
    "box"                       box,
    "bytea"                     bytea,
    "character"                 character(10)                    NOT NULL,
    "character_varying"         character varying(255) DEFAULT 'a',
    "cidr"                      cidr,
    "circle"                    circle,
    "date"                      date,
    "double_precision"          double precision,
    "inet"                      inet,
    "integer"                   integer                DEFAULT 1 NOT NULL,
    "interval" interval,
    "json"                      json,
    "jsonb"                     jsonb,
    "line"                      line,
    "lseg"                      lseg,
    "macaddr"                   macaddr,
    "macaddr8"                  macaddr8,
    "money"                     money,
    "numeric"                   numeric(10, 2),
    "path"                      path,
    "pg_lsn"                    pg_lsn,
    "pg_snapshot"               pg_snapshot,
    "point"                     point,
    "polygon"                   polygon,
    "real"                      real,
    "smallint"                  smallint,
    "text"                      text,
    "time"                      time,
    "time2"                     time(3),
    "time_with_time_zone"       time with time zone,
    "time_with_time_zone2"      time(3) with time zone,
    "timestamp"                 timestamp,
    "timestamp2"                timestamp(3),
    "timestamp_with_time_zone"  timestamp with time zone,
    "timestamp_with_time_zone2" timestamp(3) with time zone,
    "tsquery"                   tsquery,
    "tsvector"                  tsvector,
    "txid_snapshot"             txid_snapshot,
    "uuid"                      uuid,
    "xml"                       xml
);

COMMENT
ON TABLE tb_demo IS 'table comment';
COMMENT
ON COLUMN tb_demo.serial IS 'serial';
COMMENT
ON COLUMN tb_demo.bigserial IS 'bigserial';
COMMENT
ON COLUMN tb_demo.bigint IS 'bigint generated by default as identity';
COMMENT
ON COLUMN tb_demo.bigint_arr IS 'bigint[]';
COMMENT
ON COLUMN tb_demo.bit IS 'bit(5)';
COMMENT
ON COLUMN tb_demo.bit_varying IS 'bit varying(255)';
COMMENT
ON COLUMN tb_demo.boolean IS 'boolean';
COMMENT
ON COLUMN tb_demo.box IS 'box';
COMMENT
ON COLUMN tb_demo.bytea IS 'bytea';
COMMENT
ON COLUMN tb_demo.character IS 'character(255) NOT NULL';
COMMENT
ON COLUMN tb_demo.character_varying IS 'character varying(255) DEFAULT ''a''';
COMMENT
ON COLUMN tb_demo.cidr IS 'cidr';
COMMENT
ON COLUMN tb_demo.circle IS 'circle';
COMMENT
ON COLUMN tb_demo.date IS 'date';
COMMENT
ON COLUMN tb_demo.double_precision IS 'double precision';
COMMENT
ON COLUMN tb_demo.inet IS 'inet';
COMMENT
ON COLUMN tb_demo.integer IS 'integer DEFAULT 1 NOT NULL';
COMMENT
ON COLUMN tb_demo.interval IS 'interval';
COMMENT
ON COLUMN tb_demo.json IS 'json';
COMMENT
ON COLUMN tb_demo.jsonb IS 'jsonb';
COMMENT
ON COLUMN tb_demo.line IS 'line';
COMMENT
ON COLUMN tb_demo.lseg IS 'lseg';
COMMENT
ON COLUMN tb_demo.macaddr IS 'macaddr';
COMMENT
ON COLUMN tb_demo.macaddr8 IS 'macaddr8';
COMMENT
ON COLUMN tb_demo.money IS 'money';
COMMENT
ON COLUMN tb_demo.numeric IS 'numeric(10, 2)';
COMMENT
ON COLUMN tb_demo.path IS 'path';
COMMENT
ON COLUMN tb_demo.pg_lsn IS 'pg_lsn';
COMMENT
ON COLUMN tb_demo.pg_snapshot IS 'pg_snapshot';
COMMENT
ON COLUMN tb_demo.point IS 'point';
COMMENT
ON COLUMN tb_demo.polygon IS 'polygon';
COMMENT
ON COLUMN tb_demo.real IS 'real';
COMMENT
ON COLUMN tb_demo.smallint IS 'smallint';
COMMENT
ON COLUMN tb_demo.text IS 'text';
COMMENT
ON COLUMN tb_demo.time IS 'time';
COMMENT
ON COLUMN tb_demo.time_with_time_zone IS 'time with time zone';
COMMENT
ON COLUMN tb_demo.timestamp IS 'timestamp';
COMMENT
ON COLUMN tb_demo.timestamp_with_time_zone IS 'timestamp with time zone';
COMMENT
ON COLUMN tb_demo.tsquery IS 'tsquery';
COMMENT
ON COLUMN tb_demo.tsvector IS 'tsvector';
COMMENT
ON COLUMN tb_demo.txid_snapshot IS 'txid_snapshot';
COMMENT
ON COLUMN tb_demo.uuid IS 'uuid';
COMMENT
ON COLUMN tb_demo.xml IS 'xml';